import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify'
import type { Prisma } from '@prisma/client'
import { articleView } from '../lib/views.js'

const DEFAULT_LIMIT = 20
const DEFAULT_OFFSET = 0

type ListQuery = {
  tag?: string
  author?: string
  favorited?: string
  limit?: string
  offset?: string
}

// limit/offset은 쿼리스트링이라 문자열로 들어온다. 숫자로 파싱하되 유효하지 않으면 기본값.
function parsePaging(q: { limit?: string; offset?: string }): { limit: number; offset: number } {
  const limit = Number(q.limit)
  const offset = Number(q.offset)
  return {
    limit: Number.isFinite(limit) && limit > 0 ? Math.floor(limit) : DEFAULT_LIMIT,
    offset: Number.isFinite(offset) && offset >= 0 ? Math.floor(offset) : DEFAULT_OFFSET,
  }
}

// 현재 유저가 팔로우하는 저자 id 집합을 단일 쿼리로 계산 (N+1 방지).
async function followingSet(
  app: FastifyInstance,
  meId: number | undefined,
  authorIds: number[],
): Promise<Set<number>> {
  if (!meId || authorIds.length === 0) return new Set<number>()
  const rows = await app.prisma.follow.findMany({
    where: { followerId: meId, followingId: { in: authorIds } },
    select: { followingId: true },
  })
  return new Set(rows.map((r) => r.followingId))
}

// articleView가 필요로 하는 author/tags + favorited 계산용 favoritedBy를 함께 로드.
const includeArticle = {
  author: true,
  tags: true,
  favoritedBy: true,
} satisfies Prisma.ArticleInclude

// where에 매칭되는 글을 조회해 RealWorld 목록 응답으로 직렬화한다.
// articlesCount는 페이지가 아니라 필터 전체 매칭 개수(count({where})).
async function listArticles(
  app: FastifyInstance,
  where: Prisma.ArticleWhereInput,
  meId: number | undefined,
  limit: number,
  offset: number,
) {
  const [rows, articlesCount] = await Promise.all([
    app.prisma.article.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
      skip: offset,
      include: includeArticle,
    }),
    app.prisma.article.count({ where }),
  ])

  const fset = await followingSet(
    app,
    meId,
    rows.map((a) => a.authorId),
  )

  const articles = rows.map(
    (a) =>
      articleView(a, {
        favorited: meId ? a.favoritedBy.some((f) => f.userId === meId) : false,
        favoritesCount: a.favoritedBy.length,
        following: fset.has(a.authorId),
        includeBody: false, // 목록/피드 응답은 body 미포함 (2024-08-16 스펙)
      }).article,
  )

  return { articles, articlesCount }
}

export default async function (app: FastifyInstance) {
  // GET /api/articles — 전역 목록 (인증 선택)
  app.get(
    '/articles',
    { preHandler: app.authOptional },
    async (req: FastifyRequest, reply: FastifyReply) => {
      const q = req.query as ListQuery
      const { limit, offset } = parsePaging(q)

      const where: Prisma.ArticleWhereInput = {}
      if (q.tag) where.tags = { some: { name: q.tag } }
      if (q.author) where.author = { username: q.author }
      if (q.favorited) where.favoritedBy = { some: { user: { username: q.favorited } } }

      const result = await listArticles(app, where, req.user?.id, limit, offset)
      return reply.send(result)
    },
  )

  // GET /api/articles/feed — 팔로우한 저자들의 글 (인증 필수)
  app.get(
    '/articles/feed',
    { preHandler: app.authenticate },
    async (req: FastifyRequest, reply: FastifyReply) => {
      const q = req.query as { limit?: string; offset?: string }
      const { limit, offset } = parsePaging(q)
      const meId = req.user!.id // authenticate 통과 시 항상 존재

      // 저자를 팔로우하는 Follow 중 followerId가 나인 것 → 내가 팔로우하는 저자의 글.
      const where: Prisma.ArticleWhereInput = {
        author: { followedBy: { some: { followerId: meId } } },
      }

      const result = await listArticles(app, where, meId, limit, offset)
      return reply.send(result)
    },
  )
}

